command:
set -e; git show origin/agent-control:.agent/scripts/apply-climate-detail-unify-v1.py > /tmp/apply-climate-detail-unify-v1.py; python3 - <<'PY'
p='/tmp/apply-climate-detail-unify-v1.py'
lines=open(p).read().splitlines()
hits=[i for i,line in enumerate(lines) if line.strip().startswith('relay_end = text.find(')]
if len(hits) != 1: raise SystemExit(f'unexpected relay_end anchors: {hits}')
i=hits[0]
if 'relay_start' not in lines[i]: raise SystemExit('relay_end anchor does not reference relay_start')
lines[i]=lines[i].replace('relay_start','health_start',1)
open(p,'w').write('\n'.join(lines)+'\n')
PY
python3 /tmp/apply-climate-detail-unify-v1.py; mkdir -p apps/mobile/src/components/icons; cat > apps/mobile/src/components/icons/CodeIcon.tsx <<'EOF'
import { IconCode } from '@tabler/icons-react';

export const CodeIcon = () => (
  <IconCode className="icon-action__svg" aria-hidden="true" />
);
EOF
pnpm exec prettier --write apps/mobile/src/components/AppBottomNavigation.tsx apps/mobile/src/components/AppBottomNavigation.css apps/mobile/src/components/RefreshIconButton.tsx apps/mobile/src/components/icons/CodeIcon.tsx apps/mobile/src/app/App.tsx apps/mobile/src/app/appShell.css apps/mobile/src/routes/AppRoutes.tsx apps/mobile/src/screens/AutomationDashboardScreen.tsx apps/mobile/src/screens/AutomationDashboardScreen.css apps/mobile/src/screens/InstallationDetailScreen.tsx apps/mobile/src/screens/ShellyLedSettingsCard.tsx apps/mobile/src/theme/theme.css apps/mobile/src/__tests__/automation-detail.test.tsx apps/mobile/src/__tests__/app-routes.test.tsx; git diff --check; test -z "$(grep -n '<svg' apps/mobile/src/app/App.tsx apps/mobile/src/components/AppBottomNavigation.tsx apps/mobile/src/components/RefreshIconButton.tsx apps/mobile/src/components/icons/CodeIcon.tsx apps/mobile/src/screens/InstallationDetailScreen.tsx || true)"; test -z "$(grep -n 'CodeIcon' apps/mobile/src/screens/InstallationDetailScreen.tsx || true)"; grep -q "@tabler/icons-react" apps/mobile/src/components/icons/CodeIcon.tsx; test -z "$(grep -n 'RefreshIconButton' apps/mobile/src/screens/InstallationDetailScreen.tsx apps/mobile/src/screens/ShellyLedSettingsCard.tsx || true)"; grep -q 'AppBottomNavigation' apps/mobile/src/screens/AutomationDashboardScreen.tsx; grep -q 'AppBottomNavigation' apps/mobile/src/screens/InstallationDetailScreen.tsx; grep -q 'IconCode' apps/mobile/src/screens/InstallationDetailScreen.tsx; grep -q 'IconRefresh' apps/mobile/src/components/RefreshIconButton.tsx; pnpm quality:ux; pnpm --filter @lcl/mobile lint; pnpm --filter @lcl/mobile typecheck; pnpm --filter @lcl/mobile test; pnpm --filter @lcl/mobile build; echo CLIMATE_DETAIL_SOURCE_TESTS_OK
